create extension if not exists pgcrypto;
create table if not exists app_settings(id uuid primary key default gen_random_uuid(), key text unique not null, value text not null default '', updated_at timestamptz default now());
create table if not exists teachers(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, credentials text, phone text, address text, created_at timestamptz default now());
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, class_level int check(class_level between 4 and 12), role text not null default 'student' check(role in ('student','teacher','admin')), approval_status text not null default 'pending' check(approval_status in ('pending','approved','blocked')), created_at timestamptz default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(), title text not null, description text, class_level int, subject text, price numeric default 0, banner_url text, active boolean default true, created_at timestamptz default now());
create table if not exists materials(id uuid primary key default gen_random_uuid(), course_id uuid references courses(id) on delete cascade, title text not null, type text not null check(type in ('pdf','video','link')), url text not null, created_at timestamptz default now());
create table if not exists homework(id uuid primary key default gen_random_uuid(), title text not null, description text, class_level int, due_at timestamptz, created_at timestamptz default now());
create table if not exists homework_submissions(id uuid primary key default gen_random_uuid(), homework_id uuid references homework(id) on delete cascade, student_id uuid references profiles(id) on delete cascade, file_url text, answer_text text, status text default 'submitted' check(status in ('submitted','checked','needs_improvement')), remarks text, submitted_at timestamptz default now());
create table if not exists tests(id uuid primary key default gen_random_uuid(), title text not null, class_level int, duration_minutes int default 30, total_marks int default 0, active boolean default true, created_at timestamptz default now());
create table if not exists test_questions(id uuid primary key default gen_random_uuid(), test_id uuid references tests(id) on delete cascade, question text not null, option_a text not null, option_b text not null, option_c text not null, option_d text not null, correct_option text not null check(correct_option in ('A','B','C','D')), explanation text);
create table if not exists test_attempts(id uuid primary key default gen_random_uuid(), test_id uuid references tests(id) on delete cascade, student_id uuid references profiles(id) on delete cascade, score numeric default 0, percentage numeric default 0, answers jsonb default '{}'::jsonb, started_at timestamptz default now(), submitted_at timestamptz);
create table if not exists attendance(id uuid primary key default gen_random_uuid(), student_id uuid references profiles(id) on delete cascade, attendance_date date not null, status text not null check(status in ('present','absent','leave')), unique(student_id,attendance_date));
create table if not exists payments(id uuid primary key default gen_random_uuid(), student_id uuid references profiles(id) on delete cascade, course_id uuid references courses(id) on delete set null, amount numeric not null, transaction_id text, screenshot_url text, status text default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz default now());
insert into app_settings(key,value) values ('coaching_name','ज्ञान की पाठशाला'),('tagline','पढ़ो • सीखो • आगे बढ़ो • सफलता पाओ'),('teacher_name','आकाश सर'),('phone','9758002675'),('address','Village Parwana, Bulandshahr, UP - 203407'),('notice','ज्ञान की पाठशाला में आपका स्वागत है।'),('upi_qr_url','') on conflict(key) do nothing;
alter table app_settings enable row level security; alter table profiles enable row level security; alter table courses enable row level security; alter table materials enable row level security; alter table homework enable row level security; alter table homework_submissions enable row level security; alter table tests enable row level security; alter table test_questions enable row level security; alter table test_attempts enable row level security; alter table attendance enable row level security; alter table payments enable row level security;
create policy "public settings read" on app_settings for select using(true); create policy "public courses read" on courses for select using(active=true); create policy "public materials read" on materials for select using(true); create policy "own profile read" on profiles for select using(auth.uid()=id); create policy "own attendance read" on attendance for select using(auth.uid()=student_id); create policy "own attempts" on test_attempts for all using(auth.uid()=student_id) with check(auth.uid()=student_id); create policy "own payments" on payments for all using(auth.uid()=student_id) with check(auth.uid()=student_id); create policy "own submissions" on homework_submissions for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
